-- استرجاع تعديل عدد الفصول حسب كشف الإعدادي (2026-10-22) — الفصل الدراسي الأول
begin;
-- 1) حذف الفصول الثلاثة المضافة
delete from public.school_classes c using public.schools s
 where s.id = c.school_id and c.term_id = 'c1db173e-d123-4b00-84c3-301f3c4e6072'
   and (s.name, c.class_name) in (('الكراتية','1/4'),('الخرانقة ع القديمة','1/5'),('المقربية ع','3/4'));
-- 2) إعادة الفصول الستة عشر المحذوفة بنفس المعرّفات (المواد المقررة تُضاف تلقائيًا بالـ trigger)
-- 3) إعادة schools.class_count
update public.schools s set class_count = v.n from (values
 ('قوص ع بنات',15),('البهاء زهير ع',14),('د / عبدالعزيز القوصي',23),('المخزن الاعدادية',18),('الشهيد شحات',12),('العليقات الاعدادية',17),
 ('العبور حجازة',7),('كوبري حجازة',6),('عمر بن عبدالعزيز',22),('الكراتية',9),('الخرانقة ع القديمة',10),('المقربية ع',11)) v(name,n)
 where s.name = v.name;
commit;
